mapper.select:
select distinct FIN_PRODUCT.FINPROD_MARKET_ID id, FIN_PRODUCT.FINPROD_ABBR text, FIN_PRODUCT.FINPROD_ID object, FIN_CASH_INFO.CASH_ID col from FIN_PRODUCT INNER JOIN PTL_MANAGE_OBJ ON PTL_MANAGE_OBJ.MANAGE_OBJ_ID = FIN_PRODUCT.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID, FIN_CASH_INFO
where FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR} AND FIN_PRODUCT.PROFIT_TYPE in (#{profitType,jdbcType=VARCHAR},#{profitType2,jdbcType=VARCHAR}) AND FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND FIN_CASH_INFO.CASH_TYPE_1=#{cashType1,jdbcType=VARCHAR} AND FIN_PRODUCT.P_FINPROD_ID IS NULL
AND FIN_PRODUCT.FINPROD_MARKET_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%'))
AND FIN_PRODUCT.FINPROD_MARKET_ID = #{initValue,jdbcType=VARCHAR}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
